    def transform(self, tree):
        # Tree to postfix
        rev_postfix = []
        q = [tree]
        while q:
            t = q.pop()
            rev_postfix.append(t)
            if isinstance(t, Tree):
                q += t.children

        # Postfix to tree
        stack = []
        for x in reversed(rev_postfix):
            if isinstance(x, Tree):
                size = len(x.children)
                if size:
                    args = stack[-size:]
                    del stack[-size:]
                else:
                    args = []
                try:
                    result = self._call_userfunc(x, args)
                except Discard:
                    if x is tree:
                        raise
                else:
                    stack.append(result)
            elif self.__visit_tokens__ and isinstance(x, Token):
                try:
                    result = self._call_userfunc_token(x)
                except Discard:
                    pass
                else:
                    stack.append(result)
            else:
                stack.append(x)

        if not stack:
            # Root was discarded
            return None
        t, = stack  # We should have only one tree remaining
        return t
